gameflow_node_gf_start_1759678514247:
    ; Start Node - transition to first connected node
    ld hl, gameflow_node_gfn_1759678521278
    jp execute_gameflow_node

gameflow_node_gfn_1759678521278:
    ; WorldLink Node - Load world: worldmap_1759678413935
    call init_sprites
    call init_components
    call init_entities
    call load_world_worldmap_1759678413935
    ; CRITICAL: Set game flow state and update sprites to VRAM
